int ieee80211_radiotap_iterator_init(struct ieee80211_radiotap_iterator *iterator,
                                     struct ieee80211_radiotap_header *radiotap_header,
                                     int max_length,
                                     const struct ieee80211_radiotap_vendor_namespaces *vns) {
    const uint8_t *cursor;
    uint32_t align;
    uint32_t i;
    uint32_t bit;

    iterator->i_header = radiotap_header;
    iterator->i_error = 0;
    iterator->i_index = 0;
    iterator->i_vendor = NULL;
    iterator->i_vendor_data = NULL;
    iterator->i_vendor_len = 0;
    iterator->i_next_index = 0;

    if (max_length < sizeof(*radiotap_header)) {
        iterator->i_error = -EINVAL;
        return -EINVAL;
    }

    cursor = (uint8_t *)radiotap_header;
    iterator->i_cursor = cursor;
    iterator->i_end = cursor + max_length;

    if (radiotap_header->it_version != 0) {
        iterator->i_error = -EINVAL;
        return -EINVAL;
    }

    align = 0;
    if (radiotap_header->it_present[0] & 0x01)
        align |= 0x01;
    if (radiotap_header->it_present[0] & 0x02)
        align |= 0x02;
    if (radiotap_header->it_present[0] & 0x04)
        align |= 0x04;
    if (radiotap_header->it_present[0] & 0x08)
        align |= 0x08;

    for (i = 0; i < 4; i++) {
        for (bit = 0; bit < 8; bit++) {
            if (i == 0 && bit == 0)
                continue;
            if (i == 0 && bit == 1)
                continue;
            if (i == 0 && bit == 2)
                continue;
            if (i == 0 && bit == 3)
                continue;
            if ((radiotap_header->it_present[i] >> bit) & 0x01) {
                if ((cursor + sizeof(uint32_t)) > iterator->i_end)
                    break;
                cursor += sizeof(uint32_t);
            }
        }
    }

    iterator->i_cursor = cursor;
    return 0;
}

int ieee80211_radiotap_iterator_init(struct ieee80211_radiotap_iterator *iterator,
                                     const struct ieee80211_radiotap_header *radiotap_header,
                                     int max_length,
                                     const struct ieee80211_radiotap_vendor_namespaces *vns) {
    unsigned char *cursor;
    uint64_t present;

    if (!iterator || !radiotap_header || max_length < RTAP_HDR_LEN)
        return -EINVAL;

    iterator->radiotap_header = radiotap_header;
    iterator->max_length = max_length;
    iterator->vns = vns;
    iterator->is_first = 1;
    iterator->cursor = (unsigned char *)radiotap_header + RTAP_HDR_LEN;
    iterator->align = 0;
    iterator->field = 0;
    iterator->arg = 0;

    present = le16toh(radiotap_header->present);

    if (present & IEEE80211_RADIOTAP_EXT) {
        if (max_length < 2 * RTAP_HDR_LEN)
            return -EINVAL;
        present = le64toh(*((uint64_t *)iterator->cursor));
        iterator->cursor += RTAP_HDR_LEN;
    }

    iterator->present = present;

    return 0;
}

int ieee80211_radiotap_iterator_init(struct ieee80211_radiotap_iterator *iterator,
                                     struct ieee80211_radiotap_header *radiotap_header,
                                     int max_length,
                                     const struct ieee80211_radiotap_vendor_namespaces *vns) {
    int ret = -EINVAL;

    if (!iterator || !radiotap_header || max_length < 0) {
        return ret;
    }

    if (radiotap_header->it_version != 0) {
        return ret;
    }

    iterator->rtheader = radiotap_header;
    iterator->max_length = max_length;
    iterator->vns = vns;
    iterator->this_arg = NULL;
    iterator->is_radiotap = 0;

    if (radiotap_header->it_len < sizeof(struct ieee80211_radiotap_header)) {
        return ret;
    }

    iterator->cursor = 0;
    iterator->next_index = 0;
    iterator->ext = 0;

    if ((radiotap_header->it_present >> 31) & 1) {
        iterator->has_next = 1;
    } else {
        iterator->has_next = 0;
    }

    ret = 0;
    return ret;
}

int ieee80211_radiotap_iterator_init(struct ieee80211_radiotap_iterator *iterator,
                                    struct ieee80211_radiotap_header *radiotap_header,
                                    int max_length,
                                    const struct ieee80211_radiotap_vendor_namespaces *vns) {
    int i;

    if (!iterator || !radiotap_header || max_length < RTAP_HDR_LEN) {
        return -EINVAL;
    }

    iterator->i_hdr = radiotap_header;
    iterator->i_error = 0;
    iterator->i_current_node = 0;
    iterator->i_cursor = RTAP_HDR_LEN;
    iterator->i_remaining = max_length - RTAP_HDR_LEN;
    iterator->i_v.ns = vns;
    iterator->i_v.vendor_data = NULL;
    iterator->i_v.vendor_length = 0;
    iterator->i_v.vendor_next = NULL;

    if (iterator->i_hdr->it_version != 0) {
        return -EINVAL;
    }

    for (i = 0; i < 4; i++) {
        uint32_t bitset = i == 0 ? le16toh(iterator->i_hdr->it_present) :
                            i == 1 ? le32toh(iterator->i_hdr->it_present_ext0) :
                            i == 2 ? le32toh(iterator->i_hdr->it_present_ext1) :
                                     le32toh(iterator->i_hdr->it_present_ext2);

        if (!bitset)
            continue;

        for (; bitset; iterator->i_current_node++, bitset >>= 1) {
            if (bitset & 1) {
                int datalen;
                int offset;

                if (iterator->i_current_node >= IEEE80211_RADIOTAP_NUM_ITEMS)
                    return -EINVAL;

                offset = ieee80211_radiotap_align[iterator->i_current_node];
                datalen = ieee80211_radiotap_length[iterator->i_current_node];

                if (i == 0 && (iterator->i_current_node == IEEE80211_RADIOTAP_EXT))
                    continue;

                if (offset > iterator->i_remaining || datalen > iterator->i_remaining - offset) {
                    iterator->i_error = -EINVAL;
                    return -EINVAL;
                }

                iterator->i_cursor += offset;
                iterator->i_remaining -= offset;
            }
        }
    }

    return 0;
}

int ieee80211_radiotap_iterator_init(struct ieee80211_radiotap_iterator *iterator,
                                    struct ieee80211_radiotap_header *radiotap_header,
                                    int max_length,
                                    const struct ieee80211_radiotap_vendor_namespaces *vns) {
    size_t len;
    const u_int8_t *cursor;

    if (!iterator || !radiotap_header)
        return -EINVAL;

    cursor = (const u_int8_t *)radiotap_header;
    len = RTAP_HDR_LEN(radiotap_header);

    if (len < sizeof(struct ieee80211_radiotap_header))
        return -EINVAL;

    if (len > max_length)
        return -EINVAL;

    iterator->hdr = radiotap_header;
    iterator->max_length = max_length;
    iterator->vns = vns;
    iterator->current = cursor + sizeof(struct ieee80211_radiotap_header);
    iterator->end = cursor + len;

    if (radiotap_header->it_version != 0)
        iterator->has_80211_header = 0;
    else
        iterator->has_80211_header = 1;

    if (radiotap_header->it_pad != 0)
        return -EINVAL;

    return 0;
}
